package com.kidsvideo.app;

import android.app.Activity;import android.graphics.Color;import android.os.Bundle;import android.text.InputType;import android.widget.*;

public class ParentSettingsActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Prefs p=new Prefs(this);ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,24),Ui.dp(this,24),Ui.dp(this,24),Ui.dp(this,40));root.setBackgroundColor(Color.rgb(15,15,15));sc.addView(root);TextView t=label("Parent settings",28);t.setTypeface(null,1);root.addView(t);EditText key=input("YouTube API key",p.apiKey());root.addView(key);EditText pin=input("Parent PIN",p.parentPin());pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);root.addView(pin);EditText min=input("Minimum video length (minutes)",String.valueOf(p.minVideoMinutes()));min.setInputType(InputType.TYPE_CLASS_NUMBER);root.addView(min);EditText limit=input("Daily viewing limit in minutes (0 = off)",String.valueOf(p.dailyLimitMinutes()));limit.setInputType(InputType.TYPE_CLASS_NUMBER);root.addView(limit);Spinner voice=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"British English (en-GB)","American English (en-US)"});voice.setAdapter(a);voice.setSelection(p.voiceLocale().equals("en-US")?1:0);root.addView(label("Speaking voice",15));root.addView(voice);CheckBox convo=new CheckBox(this);convo.setText("Offer spoken-English conversation after videos");convo.setTextColor(Color.WHITE);convo.setChecked(p.autoConversation());root.addView(convo);EditText blocked=input("Blocked words (comma separated)",p.blockedKeywords());blocked.setMinLines(2);root.addView(blocked);TextView note=label("Son profile permanently starts with Minecraft, gaming, LEGO, Dude Perfect and MrBeast-style terms blocked. You can add more terms here. New channels can be added in a later update without exposing normal YouTube search.",14);note.setTextColor(Color.LTGRAY);root.addView(note);Button save=new Button(this);save.setText("Save settings");save.setAllCaps(false);save.setOnClickListener(v->{p.setApiKey(key.getText().toString());p.setParentPin(pin.getText().toString());try{p.setMinVideoMinutes(Integer.parseInt(min.getText().toString()));}catch(Exception ignored){}try{p.setDailyLimitMinutes(Integer.parseInt(limit.getText().toString()));}catch(Exception ignored){}p.setVoiceLocale(voice.getSelectedItemPosition()==1?"en-US":"en-GB");p.setAutoConversation(convo.isChecked());p.setBlockedKeywords(blocked.getText().toString());p.clearCache();Toast.makeText(this,"Saved",Toast.LENGTH_SHORT).show();finish();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Ui.dp(this,20);root.addView(save,lp);Button clear=new Button(this);clear.setText("Clear watch history and favourites");clear.setAllCaps(false);clear.setOnClickListener(v->{p.clearHistory();p.clearFavorites();Toast.makeText(this,"Cleared",Toast.LENGTH_SHORT).show();});root.addView(clear);setContentView(sc);}
 private TextView label(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,6));return v;} private EditText input(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(Color.GRAY);e.setTextColor(Color.WHITE);e.setText(value);e.setSingleLine(false);e.setPadding(Ui.dp(this,8),Ui.dp(this,10),Ui.dp(this,8),Ui.dp(this,10));return e;}
}
